CREATE TABLE `sys_models_fields` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
  `uuid` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'uuid',
  `models_uuid` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '关联sys_models的uuid',
  `name` varchar(50) DEFAULT NULL COMMENT '字段名',
  `comment` varchar(255) DEFAULT NULL COMMENT '字段说明',
  `type` enum('STRING','TEXT','BOOLEAN','INTEGER','BIGINT','FLOAT','DOUBLE','DECIMAL','ENUM','DATE','DATEONLY','UUID','JSON') DEFAULT NULL COMMENT '字段类型',
  `enumValue` text COMMENT '枚举值',
