  `booleantype` varchar(50) DEFAULT NULL COMMENT 'BOOLEAN类型',
  `defaultValue` varchar(255) DEFAULT NULL COMMENT '默认值',
  `lengths` int DEFAULT NULL COMMENT '长度',
  `point` int DEFAULT NULL COMMENT '小数点',
  `primaryKey` tinyint(1) DEFAULT '0' COMMENT '主键',
  `defaulttonow` tinyint(1) DEFAULT '0' COMMENT '默认当前时间',
  `allowNull` tinyint(1) DEFAULT '0' COMMENT '必填',
